import { readFileSync } from "fs";

const lines = readFileSync(0, "utf8").trim().split("\n");
const n = Number(lines[0]);
const people = lines.slice(1, n + 1).map((l) => {
  const [name, score] = l.split(" ");
  return { name, score: Number(score) };
});

people.sort((p, q) => {
  if (p.score !== q.score) return q.score - p.score; // 点数は降順
  return p.name < q.name ? -1 : 1; // 名前は昇順
});
console.log(people.map((p) => p.name).join("\n"));
